	@Test
	void ordinaryFiltersAndComputedProjectionsRetainRowsAcrossAutomaticPhysicalChoices() {
		String input = "GRAPH <" + EX + "visible> { ?s <" + EX + "left> ?left . ?s <" + EX
				+ "right> ?right }";
		List<String> queries = List.of(
				"SELECT ?s (STRLEN(STRAFTER(CONCAT(?left, \"|\", ?right), \"|\")) AS ?value) WHERE { "
						+ input + " }",
				"SELECT ?s WHERE { " + input + " FILTER(REGEX(CONCAT(?left, \"|\", ?right), \"^α.*x$\", \"s\")) }",
				"SELECT ?s WHERE { " + input + " FILTER(CONTAINS(?left, \"α\")) }",
				"SELECT ?s (STRLEN(CONCAT(?left, ?right)) AS ?value) WHERE { VALUES ?duplicate { 1 1 } "
						+ input + " }",
				"SELECT ?s ?value WHERE { VALUES ?needle { \"x\" \"yz\" \"x\" } { SELECT ?s ?left ?right WHERE { "
						+ input
						+ " } } FILTER(CONTAINS(?right, ?needle)) BIND(STRLEN(CONCAT(?left, ?right)) AS ?value) }",
				"SELECT ?s WHERE { GRAPH <" + EX + "visible> { ?s <" + EX + "left> ?left } FILTER EXISTS { GRAPH <"
						+ EX + "visible> { ?s <" + EX
						+ "right> ?right } FILTER(REGEX(CONCAT(?left, ?right), \"^α.*x$\")) } }",
				"SELECT ?s ?value WHERE { { " + input + " FILTER(CONTAINS(?left, \"α\")) } UNION { " + input
						+ " FILTER(CONTAINS(?right, \"yz\")) } BIND(STRLEN(CONCAT(?left, ?right)) AS ?value) }",
				"SELECT ?s ?value WHERE { " + input
						+ " OPTIONAL { VALUES ?needle { \"α\" \"absent\" } FILTER(CONTAINS(?left, ?needle)) "
						+ "BIND(STRLEN(?left) AS ?value) } MINUS { VALUES ?right { \"x\" } FILTER(CONTAINS(?right, \"x\")) } }");
		int[] counts = { 128, 22, 64, 256, 171, 22, 149, 85 };
		for (int index = 0; index < queries.size(); index++) {
			String query = queries.get(index);
			List<BindingSet> expected = evaluate(query, false);
			assertThat(expected).as("generic row admission for variant %s", index).hasSize(counts[index]);
			long evaluations = NativeExpressionDomain.EVALUATIONS.get();
			assertThat(evaluate(query, true)).as("native row semantics for variant %s", index)
					.containsExactlyInAnyOrderElementsOf(expected);
			assertThat(NativeExpressionDomain.EVALUATIONS.get()).as("actual scalar work for variant %s", index)
					.isGreaterThan(evaluations);
		}
		assertThat(telemetry(queries.getFirst())).contains("nativeRowTermDomainHitsActual",
				"nativeRowTermDomainEvaluationsActual", "nativeRowTermDomainIoReadsActual",
				"nativeRowTermDomainIoWritesActual");
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void actualNativeValuesProducerSelectsAutomaticLastTupleReuse(boolean filterOnly) {
		StringBuilder values = new StringBuilder();
		for (int ordinal = 0; ordinal < 128; ordinal++) {
			values.append('(').append(ordinal).append(ordinal < 64 ? " \"α😀\") " : " \"shared\") ");
		}
		String query = (filterOnly ? "SELECT ?ordinal WHERE { VALUES (?ordinal ?text) { "
				: "SELECT ?ordinal (STRLEN(CONCAT(?text, \"!\")) AS ?length) WHERE { VALUES (?ordinal ?text) { ")
				+ values + (filterOnly ? " } FILTER(REGEX(CONCAT(?text, \"!\"), \".*!$\")) }" : " } }");
		List<BindingSet> expected = evaluate(query, false);
		assertThat(expected).hasSize(128);
		long hits = NativeExpressionDomain.HITS.get();
		long spills = NativeExpressionDomain.SPILL_FILES_CREATED.get();
		long reads = NativeExpressionDomain.IO_READ_OPERATIONS.get();
		long writes = NativeExpressionDomain.IO_WRITE_OPERATIONS.get();
		System.setProperty(NATIVE, "true");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			// Select an existing row producer. The scalar reuse policy remains AUTO and must prove its own order.
			prepared.setForcedLmdbExecutionStrategy("nestedLoop");
			try (var result = prepared.evaluate()) {
				assertThat(QueryResults.asList(result)).containsExactlyElementsOf(expected);
			}
		}
		assertThat(NativeExpressionDomain.HITS.get() - hits).isEqualTo(126);
		assertThat(NativeExpressionDomain.SPILL_FILES_CREATED.get() - spills).isZero();
		assertThat(NativeExpressionDomain.IO_READ_OPERATIONS.get() - reads).isZero();
		assertThat(NativeExpressionDomain.IO_WRITE_OPERATIONS.get() - writes).isZero();
	}

