	@Test
	void relevantTermsAndDependencyTuplesHaveExactVisibleWeights() {
		for (String expression : List.of("STRLEN(?left)", "STRLEN(CONCAT(?left, \"|\", ?right))")) {
			String query = "SELECT (SUM(" + expression + ") AS ?sum) WHERE { GRAPH <" + EX
					+ "visible> { ?s <" + EX + "left> ?left . ?s <" + EX + "right> ?right } }";
			List<BindingSet> expected = evaluate(query, false);
			assertThat(expected).hasSize(1);
			assertThat(((Literal) expected.get(0).getValue("sum")).longValue()).isPositive();
			assertThat(evaluate(query, true)).containsExactlyElementsOf(expected);
			try (SailRepositoryConnection connection = repository.getConnection()) {
				assertThat(connection.prepareTupleQuery(query).explain(Explanation.Level.Telemetry).toString())
						.contains("NativeTermDomain");
			}
		}
	}

	@Test
	void autoDependencyRecipesKeepGroupMultiplicitiesAndLegalDomainCandidates() {
		String tupleQuery = "SELECT (SUM(STRLEN(CONCAT(?left, \"|\", ?right))) AS ?sum) WHERE { GRAPH <"
				+ EX + "visible> { ?s <" + EX + "left> ?left . ?s <" + EX + "right> ?right } }";
		assertThat(evaluate(tupleQuery, true)).containsExactlyElementsOf(evaluate(tupleQuery, false));
		assertThat(telemetry(tupleQuery)).contains("NativeTermDomain");
		String grouped = "SELECT ?bucket (SUM(STRLEN(?left)) AS ?sum) (COUNT(*) AS ?count) WHERE { GRAPH <"
				+ EX + "visible> { ?s <" + EX + "left> ?left . ?s <" + EX
				+ "bucket> ?bucket } } GROUP BY ?bucket";
		assertThat(evaluate(grouped, true)).containsExactlyInAnyOrderElementsOf(evaluate(grouped, false));
		assertThat(telemetry(grouped)).contains("NativeTermDomain");
	}

